lonausa/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='bellona-usa-turkish-furniture-manufacturing-wholesale' AND approved AND profile IS NULL;
UPDATE companies SET description='Beloved Furniture operates from Elm Springs, Arkansas, where it opened a showroom in 2025. The business traces its roots to 2018, when the founder, a former procurement forester, began building furniture in a small shop in Wilmar, Arkansas under the name Breedlove Woodworking. Self-taught through online resources and inspired by surrounding sawmills, the founder shifted focus to dining tables after recognizing their role as gathering places for families.

The company designs and builds custom farmhouse tables, modern tables, benches, and solid-wood chairs. Production takes place in a workshop adjacent to the Elm Springs showroom, using premium hardwoods from seven standard species and twelve standard stain options. Each piece is made to order, with dimensions tailored to the customer’s space.

Beloved Furniture serves residential customers across Northwest Arkansas, Eastern Oklahoma, and Southern Missouri, including cities such as Bentonville, Rogers, Tulsa, and Joplin. The business sells directly to families through its showroom appointments and online custom-order process.

The founder started the venture to create furniture that lasts for generations, emphasizing handcrafted construction and personalized finishes. The showroom allows clients to review samples, test chair comfort, and finalize designs in person, reinforcing a focus on durability and customer involvement.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom woodworking", "Furniture manufacturing", "Wood staining and finishing", "Custom sizing", "Showroom consultation"], "industries": ["Residential furniture", "Custom furniture", "Home furnishings"], "materials": ["Premium hardwoods (7 standard species)", "Wood stains and finishes"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Customizable to any length or width", "Handmade from premium hardwoods", "7 standard wood species and 12 stain options", "Showroom for in-person samples and design consultation", "Built to last generations"], "facts_used": ["Location: Elm Springs, Arkansas -> /", "Founding year: 2018 (as Breedlove Woodworking) -> /", "Founder background: former procurement forester, self-taught -> /", "Products: custom farmhouse tables, modern tables, benches, solid-wood chairs -> /", "Materials: 7 standard wood species, 12 standard stain options -> /", "Showroom opened: 2025 at 10265 Snavely Road, Elm Springs, AR 72762 -> /", "Service area: Northwest Arkansas, Eastern Oklahoma, Southern Missouri (multiple cities listed) -> /", "Differentiators: customizable dimensions, handmade, premium hardwoods, showroom experience, built for generations -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Today we design and build farmhouse tables, modern tables, benches, and solid wood chairs from our shop in Elm Springs.", "founded_year": "2018", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='beloved-furniture' AND a